// Latch each MQTT message into flow.bms_state[bank][field] = {value, _ts}.
const parts = msg.topic.split('/');
const bank = parts[0];
const field = parts.slice(1).join('/');
if (!field) return null;  // skip bare-topic messages (no field)

const nowMs = Date.now();
const state = flow.get('bms_state') || {};
const bankState = state[bank] || {};
bankState[field] = { value: msg.payload, _ts: nowMs };
state[bank] = bankState;
flow.set('bms_state', state);

// --- Frozen-counter detection ----------------------------------------------
// A pack can republish a stale soc_percent indefinitely. On 2026-09-12 bat_west
// sat pinned at 46.4% from 19:00 to 06:00 UTC, and again at 47.5% for five hours
// over midday, while its own ammeter integrated 88.8 Ah into the pack for a
// registered +1.1 pp. The FRESH_MS check below cannot see that - the stale value
// keeps arriving with a fresh _ts - so the frozen pack stayed in the weighted
// average at full weight and dragged the aggregate the optimizer plans on.
// So integrate each pack's own current between its soc_percent messages: once
// more than FREEZE_FRAC of its capacity has moved with the SOC unchanged, the
// counter is not counting and the pack drops out of the SOC average. Its cell
// voltages are measured rather than integrated, so those keep counting either way.
const FREEZE_FRAC = 0.02;     // of pack capacity, ~2.4-6.2 Ah here
const FREEZE_MIN_A = 1.0;     // ignore trickle: below this a flat SOC is honest
const move = flow.get('bms_socmove') || {};
if (field === 'soc/soc_percent') {
    const m = move[bank] || {};
    const socNow = parseFloat(msg.payload);
    const curRec = bankState['soc/current'];
    const iNow = curRec ? Math.abs(parseFloat(curRec.value)) : NaN;
    const dtH = (typeof m.lastTs === 'number') ? (nowMs - m.lastTs) / 3600000 : 0;
    // Cap dt: a Node-RED restart or a broker gap must not bank hours of charge.
    if (dtH > 0 && dtH < 0.25 && isFinite(iNow) && iNow >= FREEZE_MIN_A) {
        m.ah = (m.ah || 0) + iNow * dtH;
    }
    if (!isFinite(socNow) || socNow !== m.soc) { m.ah = 0; m.soc = socNow; }
    m.lastTs = nowMs;
    move[bank] = m;
    flow.set('bms_socmove', move);
}

// --- Publish aggregate battery state to global for the battery optimizer ---
// The Victron aggregate (global.ess.Soc) is unreliable, and the packs' reported
// SOC% is miscalibrated (small packs read ~99.8% at only ~3.40 V/cell). So we
// publish both a capacity-weighted SOC (for energy planning) and the cell voltage
// extremes across packs - the true fullness and emptiness signals the optimizer
// gates charge and discharge on.
const BANKS = ['bat_ost', 'bat_west', 'bat_big'];
const FRESH_MS = 30 * 60 * 1000;
// Cell voltages get a longer window than the SOC average. A pack that has dropped
// off the BLE feed is still wired in parallel on the same DC bus, and min/max across
// packs only ever move the fleet extremes outward - folding a stale pack back in can
// only lower minCellV (the discharge gate) and only raise maxCellV (the charge gate),
// so it errs toward not moving energy in either direction. On 2026-09-14 bat_west sat
// off the feed for 4h15m behind a stale BlueZ GATT cache, and the FRESH_MS check
// dropped it before its voltages were read: minCellV published bat_ost's 3.322 V while
// bat_west - the lowest pack in the fleet, and so the one that reaches the LFP knee
// first - was invisible to the gate that exists to protect it. Past VOLT_FRESH_MS the
// last reading says nothing about the pack any more, and a sag latched at, say, 3.21 V
// would jam no-discharge for as long as the pack stayed dark, so it is dropped instead
// of held. Each field carries its own _ts, so gate on the voltage record's age rather
// than the SOC record's.
const VOLT_FRESH_MS = 6 * 60 * 60 * 1000;
let wsum = 0, csum = 0, nBanks = 0, maxSoc = null, maxCellV = null, minCellV = null, oldest = null;
const frozen = [];
const voltOnly = [];
for (const b of BANKS) {
    const bs = state[b];
    if (!bs) continue;

    let usedVolts = false;
    const cvRec = bs['cell_voltages/max'];
    if (cvRec && nowMs - cvRec._ts <= VOLT_FRESH_MS) {
        const cv = parseFloat(cvRec.value);
        if (isFinite(cv)) {
            usedVolts = true;
            if (maxCellV === null || cv > maxCellV) maxCellV = cv;
        }
    }
    const cnRec = bs['cell_voltages/min'];
    if (cnRec && nowMs - cnRec._ts <= VOLT_FRESH_MS) {
        const cn = parseFloat(cnRec.value);
        if (isFinite(cn)) {
            usedVolts = true;
            if (minCellV === null || cn < minCellV) minCellV = cn;
        }
    }

    const socRec = bs['soc/soc_percent'];
    if (!socRec || nowMs - socRec._ts > FRESH_MS) {
        // Missing or stale SOC: out of the weighted average, voltages kept above.
        // Only claim the pack if a voltage actually landed - past VOLT_FRESH_MS
        // it contributes nothing at all and should not read as half-present.
        if (usedVolts) voltOnly.push(b);
        continue;
    }

    const capRec = bs['soc/aged_capacity'] || bs['soc/capacity'];
    const cap = capRec ? parseFloat(capRec.value) : NaN;
    if (isFinite(cap) && cap > 0 && ((move[b] || {}).ah || 0) > cap * FREEZE_FRAC) {
        frozen.push(b);   // counter stuck: keep its voltages above, drop its SOC
        continue;
    }

    const soc = parseFloat(socRec.value);
    if (isFinite(soc)) {
        if (maxSoc === null || soc > maxSoc) maxSoc = soc;
        if (oldest === null || socRec._ts < oldest) oldest = socRec._ts;
        if (isFinite(cap) && cap > 0) { wsum += soc * cap; csum += cap; nBanks++; }
    }
}
// --- Victron SOC calibration offset ----------------------------------------
// The Cerbo has no battery-monitor service at all: `Settings/SystemSetup/BatteryService`
// is "default" and resolves to com.victronenergy.vebus.ttyS4, so `global.ess.Soc` is
// nothing but the MultiPlus's own coulomb counter. That counter re-zeroes only when the
// Multi completes an absorption with tail current, which the 95% planning ceiling
// guarantees will never happen, so its error is frozen wherever it last landed. On
// 2026-09-14 it read 18% against a real ~50%, and over 09-12..09-14 it sat a flat
// 18-32 pp low while tracking the true curve slope-for-slope: the shape is sound, only
// the level is wrong. `query_soc` falls back to that number once this feed is 30 min
// old, and a 26 pp understatement is exactly what makes the planner panic-buy a
// half-full pack. So carry a running correction for the level and let the fallback
// apply it. It rides in `global.bms`, which stops being rewritten when the feed dies -
// the offset that survives is therefore the last one measured while both feeds were
// healthy, and its age doubles as the age of the outage.
// Only sample when every bank is in the average: a partial fleet (bat_west has gone
// silent for hours at a time) biases the weighted SOC, while ess.Soc reads the whole
// DC bus regardless. The EMA is slow on purpose - the offset is stable over days, and
// if the Multi ever does re-zero itself the correction should decay, not snap.
const OFFSET_ALPHA = 0.02;    // ~50 soc_percent messages to converge, order of an hour
const OFFSET_MAX_PP = 50;     // beyond this one of the two feeds is broken, not offset
let offRec = global.get('bmsEssOffset', 'file') || {};
if (field === 'soc/soc_percent' && nBanks === BANKS.length && csum > 0) {
    const essSoc = parseFloat((global.get('ess') || {}).Soc);
    if (isFinite(essSoc) && essSoc >= 0 && essSoc <= 100) {
        let off = (wsum / csum) - essSoc;
        off = Math.max(-OFFSET_MAX_PP, Math.min(OFFSET_MAX_PP, off));
        const prev = (typeof offRec.pp === 'number' && isFinite(offRec.pp)) ? offRec.pp : off;
        offRec = { pp: prev + OFFSET_ALPHA * (off - prev), ts: nowMs };
        global.set('bmsEssOffset', offRec, 'file');
    }
}

if (maxSoc !== null || maxCellV !== null) {
    global.set('bms', {
        weightedSoc: csum > 0 ? Math.round((wsum / csum) * 10) / 10 : null,
        maxPackSoc: maxSoc,
        maxCellV: maxCellV,
        minCellV: minCellV,
        frozenPacks: frozen,
        voltOnlyPacks: voltOnly,
        banks: nBanks,
        essOffset: (typeof offRec.pp === 'number' && isFinite(offRec.pp))
            ? Math.round(offRec.pp * 10) / 10 : undefined,
        essOffsetTs: offRec.ts,
        ts: nowMs,
        oldestTs: oldest
    });
}
return null;

// Per-tick health checks with per-condition debounce.
//   - Statistical checks (default {active:3, clear:3}) require 3 consecutive
//     ticks (~9min @ 180s) before flipping state — suppresses BMS noise.
//   - Safety-critical checks ({active:1, clear:3}) emit 'active' on the first
//     tick the condition holds, but require 3 clear ticks before resolving.
//   - Events (bms_reboot, cycles_reset) emit one-shot, no debounce.
// Out 1 = alerts (one msg per emit, topic=checkbattery/alert)
// Out 2 = influx batch (single msg with payload=[points...])

const NOW = Date.now();
const NOW_ISO = new Date(NOW).toISOString();
const BANKS = ['bat_ost', 'bat_west', 'bat_big'];

const STATE = flow.get('bms_state') || {};
const PREV  = flow.get('bms_prev') || {};
const DB    = flow.get('bms_debounce') || {};

const TH = {
    cell_delta_warn:  0.050,
    cell_delta_alert: 0.100,
    cell_min:         2.80,
    cell_max:         3.60,
    cell_outlier:     0.030,
    temp_min:         -10,
    temp_max:         50,
    mosfet_temp_max:  60,
    comm_dropout_ms:  3 * 60 * 1000,
    // Older than this and a latched field is no longer a measurement. Looser than
    // comm_dropout_ms on purpose: one missed BLE poll (the packs sample every 60s)
    // should not punch holes in an otherwise continuous series.
    stale_write_ms:   5 * 60 * 1000
};

const DEBOUNCE = {
    no_data:               { active: 1, clear: 3 },
    comm_dropout:          { active: 1, clear: 3 },
    cell_under:            { active: 1, clear: 3 },
    cell_over:             { active: 1, clear: 3 },
    switch_charge_off:     { active: 1, clear: 3 },
    switch_discharge_off:  { active: 1, clear: 3 }
};
const DEBOUNCE_DEFAULT = { active: 3, clear: 3 };

const alerts = [];
const points = [];

function num(v) {
    if (v === undefined || v === null) return null;
    const n = parseFloat(v);
    return Number.isFinite(n) ? n : null;
}

// hold=true: condition currently violating; hold=false: currently OK.
function condition(bank, code, hold, value, severity, message) {
    const cfg = DEBOUNCE[code] || DEBOUNCE_DEFAULT;
    const bankDb = DB[bank] || (DB[bank] = {});
    let e = bankDb[code];
    if (!e) {
        e = { state: 'clear', candidate: 'clear', count: 0 };
        bankDb[code] = e;
    }
    const cand = hold ? 'active' : 'clear';
    if (cand === e.state) {
        e.candidate = cand;
        e.count = 0;
        if (hold) e.value = value;
        return;
    }
    if (cand === e.candidate) {
        e.count++;
    } else {
        e.candidate = cand;
        e.count = 1;
    }
    if (hold) e.value = value;
    const need = hold ? cfg.active : cfg.clear;
    if (e.count >= need) {
        if (hold) {
            e.state = 'active';
            e.since = NOW_ISO;
            alerts.push({
                ts: NOW_ISO, bank, severity, code, msg: message,
                value, since: NOW_ISO, state: 'active', debounceTicks: need
            });
        } else {
            const since = e.since;
            e.state = 'clear';
            delete e.since;
            alerts.push({
                ts: NOW_ISO, bank, severity: 'info', code,
                msg: 'cleared', value: null, since, state: 'cleared'
            });
        }
        e.count = 0;
    }
}

function event(bank, code, value, severity, message) {
    alerts.push({
        ts: NOW_ISO, bank, severity, code, msg: message,
        value, since: NOW_ISO, state: 'event'
    });
}

for (const bank of BANKS) {
    const s = STATE[bank];
    const get = (path) => (s && s[path]) ? num(s[path].value) : null;

    const hasData = !!s && Object.keys(s).length > 0;
    condition(bank, 'no_data', !hasData, null, 'alert', 'No data ever received from bank');
    if (!hasData) continue;

    let newestTs = 0;
    for (const k in s) if (s[k]._ts > newestTs) newestTs = s[k]._ts;
    const ageMs = NOW - newestTs;
    const ageS = Math.round(ageMs / 1000);
    condition(bank, 'comm_dropout', ageMs > TH.comm_dropout_ms, ageS, 'alert',
        `No update in ${ageS}s`);

    const cellMin   = get('cell_voltages/min');
    const cellMax   = get('cell_voltages/max');
    const cellAvg   = get('cell_voltages/average');
    const cellDelta = get('cell_voltages/delta');
    const minIdx    = get('cell_voltages/min_index');
    const maxIdx    = get('cell_voltages/max_index');

    if (cellDelta !== null) {
        const isAlertDelta = cellDelta >= TH.cell_delta_alert;
        const isWarnDelta  = !isAlertDelta && cellDelta >= TH.cell_delta_warn;
        condition(bank, 'cell_delta_alert', isAlertDelta, cellDelta, 'alert',
            `Cell delta ${(cellDelta*1000).toFixed(0)}mV >= ${TH.cell_delta_alert*1000}mV (cell ${maxIdx} high, cell ${minIdx} low)`);
        condition(bank, 'cell_delta_warn', isWarnDelta, cellDelta, 'warn',
            `Cell delta ${(cellDelta*1000).toFixed(0)}mV >= ${TH.cell_delta_warn*1000}mV (cell ${maxIdx} high, cell ${minIdx} low)`);
    }

    if (cellMin !== null) {
        condition(bank, 'cell_under', cellMin < TH.cell_min, cellMin, 'alert',
            `Cell ${minIdx} at ${cellMin.toFixed(3)}V below ${TH.cell_min}V`);
    }
    if (cellMax !== null) {
        condition(bank, 'cell_over', cellMax > TH.cell_max, cellMax, 'alert',
            `Cell ${maxIdx} at ${cellMax.toFixed(3)}V above ${TH.cell_max}V`);
    }

    if (cellAvg !== null) {
        for (let i = 1; i <= 16; i++) {
            const v = get('cell_voltages/' + i);
            if (v === null) {
                condition(bank, 'cell_outlier_' + i, false, null, 'warn', '');
                continue;
            }
            const dev = Math.abs(v - cellAvg);
            condition(bank, 'cell_outlier_' + i, dev > TH.cell_outlier, v, 'warn',
                `Cell ${i} at ${v.toFixed(3)}V deviates ${(dev*1000).toFixed(0)}mV from bank avg ${cellAvg.toFixed(3)}V`);
        }
    }

    for (const i of [1, 2]) {
        const t = get('temperatures/' + i);
        if (t === null) {
            condition(bank, 'temp_high_' + i, false, null, 'alert', '');
            condition(bank, 'temp_low_'  + i, false, null, 'alert', '');
            continue;
        }
        condition(bank, 'temp_high_' + i, t > TH.temp_max, t, 'alert',
            `Temp sensor ${i} at ${t.toFixed(1)}C above ${TH.temp_max}C`);
        condition(bank, 'temp_low_' + i, t < TH.temp_min, t, 'alert',
            `Temp sensor ${i} at ${t.toFixed(1)}C below ${TH.temp_min}C`);
    }

    const mosfetTemp = get('mosfet_status/temperature');
    if (mosfetTemp !== null) {
        condition(bank, 'mosfet_temp_high', mosfetTemp > TH.mosfet_temp_max, mosfetTemp, 'alert',
            `MOSFET temp ${mosfetTemp.toFixed(1)}C above ${TH.mosfet_temp_max}C`);
    }

    const swCharge = (s['switch/charge'] || {}).value;
    const swDisch  = (s['switch/discharge'] || {}).value;
    if (swCharge !== undefined) {
        condition(bank, 'switch_charge_off', String(swCharge) !== 'ON', swCharge, 'alert',
            `Charge switch is ${swCharge}`);
    }
    if (swDisch !== undefined) {
        condition(bank, 'switch_discharge_off', String(swDisch) !== 'ON', swDisch, 'alert',
            `Discharge switch is ${swDisch}`);
    }

    const uptime = get('bms/uptime');
    if (uptime !== null) {
        const prevUp = (PREV[bank] || {}).uptime;
        if (prevUp !== undefined && uptime < prevUp - 10000) {
            event(bank, 'bms_reboot', uptime, 'warn',
                `BMS uptime decreased: ${prevUp}ms -> ${uptime}ms (likely reboot)`);
        }
        PREV[bank] = PREV[bank] || {};
        PREV[bank].uptime = uptime;
    }

    const cycles = get('soc/num_cycles');
    if (cycles !== null) {
        const prevCyc = (PREV[bank] || {}).cycles;
        if (prevCyc !== undefined && cycles < prevCyc) {
            event(bank, 'cycles_reset', cycles, 'warn',
                `Cycle counter decreased: ${prevCyc} -> ${cycles}`);
        }
        PREV[bank] = PREV[bank] || {};
        PREV[bank].cycles = cycles;
    }

    // Per-field freshness gate on the Influx write. flow.bms_state latches the last
    // value of every field indefinitely, so a pack that goes dark keeps answering
    // with whatever it last said - and until 2026-09-14 those latched values were
    // written once per tick as if freshly measured. bat_west recorded a flat 38.31%
    // and -2.3 A from 05:30Z to 09:00Z straight through a BLE outage, which reads on
    // a graph as a pack sitting perfectly still rather than as no data at all, and
    // anything averaging bms_health across banks silently ate it. A gap is honest;
    // a carried-forward value is not. comm_dropout already alerted on this the whole
    // time - the alert fired while the writer kept fabricating the series. Gate on
    // each record's own _ts rather than the bank's newest, so one dead field cannot
    // ride in on a sibling that is still updating.
    const fresh = (path) => {
        const rec = s && s[path];
        if (!rec || NOW - rec._ts > TH.stale_write_ms) return null;
        return num(rec.value);
    };

    const fields = {};
    const map = {
        soc_percent:     'soc/soc_percent',
        total_voltage:   'soc/total_voltage',
        current:         'soc/current',
        power:           'soc/power',
        balance_current: 'soc/balance_current',
        num_cycles:      'soc/num_cycles',
        cell_delta:      'cell_voltages/delta',
        cell_min:        'cell_voltages/min',
        cell_max:        'cell_voltages/max',
        cell_avg:        'cell_voltages/average',
        capacity_ah:     'mosfet_status/capacity_ah',
        mosfet_temp:     'mosfet_status/temperature',
        temp1:           'temperatures/1',
        temp2:           'temperatures/2'
    };
    for (const fk in map) {
        const v = fresh(map[fk]);
        if (v !== null) fields[fk] = v;
    }
    if (Object.keys(fields).length > 0) {
        points.push({
            measurement: 'bms_health',
            tags: { bank },
            fields,
            timestamp: NOW
        });
    }
}

flow.set('bms_debounce', DB);
flow.set('bms_prev', PREV);

// Capacity-weighted BMS SOC -> tmp.ess.socbms. This is the same value the
// optimizer seeds predictedSoc from (global.bms.weightedSoc); logging it here
// gives the dashboard an actual-SOC line that overlays the prediction,
// instead of the Victron ess.Soc which reads ~16pt lower.
const _bms = global.get('bms');
if (_bms && typeof _bms.weightedSoc === 'number' && isFinite(_bms.weightedSoc)) {
    points.push({ measurement: 'ess', fields: { socbms: _bms.weightedSoc }, timestamp: NOW });
}

const outAlerts = alerts.map(a => ({ topic: 'checkbattery/alert', payload: a }));
const outInflux = points.length > 0 ? { payload: points } : null;
return [outAlerts, outInflux];

// Trend evaluator. Receives raw InfluxDB query result on msg.payload:
//   SELECT MEDIAN(cell_delta) FROM bms_health
//   WHERE time > now() - 24h GROUP BY time(1h), bank FILL(none)
// Per bank, fits a linear regression to the hourly medians. Emits a
// `trend_cell_delta_growth` event when slope exceeds threshold (mV/day).
// Needs >= 6 hourly buckets to fire — earlier hours just no-op.

const TH_SLOPE_MV_PER_DAY = 5;
const NOW_ISO = new Date().toISOString();

const data = msg.payload;
let series = [];
if (data && data.results && data.results[0] && Array.isArray(data.results[0].series)) {
    series = data.results[0].series;
} else if (Array.isArray(data) && data[0] && data[0].series) {
    series = data[0].series;
}
if (!series.length) {
    node.warn('trend_eval: no series in payload');
    return null;
}

const out = [];
for (const ser of series) {
    const bank = ser.tags && ser.tags.bank;
    if (!bank) continue;
    const cols = ser.columns || [];
    const tIdx = cols.indexOf('time');
    let mIdx = cols.indexOf('median');
    if (mIdx < 0) mIdx = cols.findIndex(c => typeof c === 'string' && c.indexOf('median') === 0);
    if (tIdx < 0 || mIdx < 0) continue;

    const pts = [];
    for (const row of ser.values || []) {
        const t = new Date(row[tIdx]).getTime();
        const m = parseFloat(row[mIdx]);
        if (Number.isFinite(m) && Number.isFinite(t)) pts.push([t, m]);
    }
    if (pts.length < 6) continue;

    const t0 = pts[0][0];
    let n = 0, sx = 0, sy = 0, sxx = 0, sxy = 0;
    for (const p of pts) {
        const x = (p[0] - t0) / 3600000;
        n++; sx += x; sy += p[1]; sxx += x*x; sxy += x*p[1];
    }
    const denom = n*sxx - sx*sx;
    if (denom === 0) continue;
    const slopeVPerHr = (n*sxy - sx*sy) / denom;
    const slopeMvPerDay = slopeVPerHr * 24 * 1000;

    if (slopeMvPerDay > TH_SLOPE_MV_PER_DAY) {
        out.push({
            topic: 'checkbattery/alert',
            payload: {
                ts: NOW_ISO,
                bank,
                severity: 'warn',
                code: 'trend_cell_delta_growth',
                msg: `cell_delta median trending +${slopeMvPerDay.toFixed(2)} mV/day over last 24h (n=${n} hourly buckets)`,
                value: slopeMvPerDay,
                since: NOW_ISO,
                state: 'event'
            }
        });
    }
}
return [out];

const NOW = Date.now();
const NOW_ISO = new Date(NOW).toISOString();
const BANKS = ['bat_ost', 'bat_west', 'bat_big'];
const TH = {
    cell_delta_warn:  0.050,
    cell_delta_alert: 0.100,
    cell_min:         2.80,
    cell_max:         3.60,
    cell_outlier:     0.030,
    temp_min:         -10,
    temp_max:         50,
    mosfet_temp_max:  60,
    comm_dropout_ms:  3 * 60 * 1000
};
const STATE = flow.get('bms_state') || {};

function num(v) {
    if (v === undefined || v === null) return null;
    const n = parseFloat(v);
    return Number.isFinite(n) ? n : null;
}

function build(bank) {
    const s = STATE[bank];
    if (!s || !Object.keys(s).length) {
        return { bank, hasData: false, ts: NOW_ISO, ageS: null, stale: true };
    }
    const g = (path) => (s[path] ? num(s[path].value) : null);
    const raw = (path) => (s[path] ? s[path].value : null);

    let newestTs = 0;
    for (const k in s) if (s[k]._ts > newestTs) newestTs = s[k]._ts;
    const ageMs = NOW - newestTs;
    const stale = ageMs > TH.comm_dropout_ms;

    const cellAvg = g('cell_voltages/average');
    const cellMin = g('cell_voltages/min');
    const cellMax = g('cell_voltages/max');
    const cellDelta = g('cell_voltages/delta');
    const minIdx = g('cell_voltages/min_index');
    const maxIdx = g('cell_voltages/max_index');

    const cells = [];
    for (let i = 1; i <= 16; i++) {
        const v = g('cell_voltages/' + i);
        let sev = 'na';
        let devMv = null;
        if (v !== null) {
            sev = 'ok';
            if (cellAvg !== null) {
                devMv = Math.round((v - cellAvg) * 1000);
                if (Math.abs(v - cellAvg) > TH.cell_outlier) sev = 'warn';
            }
            if (v < TH.cell_min || v > TH.cell_max) sev = 'crit';
        }
        cells.push({ i, v, devMv, sev, isMin: i === minIdx, isMax: i === maxIdx });
    }

    const t1 = g('temperatures/1');
    const t2 = g('temperatures/2');
    const mt = g('mosfet_status/temperature');
    const tempSev = (t) => t === null ? 'na' : (t < TH.temp_min || t > TH.temp_max ? 'crit' : 'ok');
    const mosfetSev = mt === null ? 'na' : (mt > TH.mosfet_temp_max ? 'crit' : 'ok');

    let deltaSev = 'na';
    if (cellDelta !== null) {
        deltaSev = 'ok';
        if (cellDelta >= TH.cell_delta_warn) deltaSev = 'warn';
        if (cellDelta >= TH.cell_delta_alert) deltaSev = 'crit';
    }

    const swCharge = raw('switch/charge');
    const swDisch  = raw('switch/discharge');
    const swBal    = raw('switch/balance');
    const swSev = (sw) => sw == null ? 'na' : (String(sw) === 'ON' ? 'ok' : 'crit');

    return {
        bank, hasData: true, ts: NOW_ISO,
        ageS: Math.round(ageMs / 1000), stale,
        soc: g('soc/soc_percent'),
        voltage: g('soc/total_voltage'),
        current: g('soc/current'),
        power: g('soc/power'),
        cycles: g('soc/num_cycles'),
        t1, t2, mt,
        tempSev1: tempSev(t1),
        tempSev2: tempSev(t2),
        mosfetSev,
        cellAvg, cellMin, cellMax, cellDelta,
        deltaSev, minIdx, maxIdx, cells,
        swCharge, swDisch, swBal,
        swChargeSev: swSev(swCharge),
        swDischSev:  swSev(swDisch),
        swBalSev:    swSev(swBal)
    };
}

function buildEss() {
    const e = global.get('ess') || {};
    const hasData = ['Soc','Voltage','Power','AcPowerSetPoint','acload','pac']
        .some(k => e[k] !== undefined && e[k] !== null);
    return {
        hasData,
        ts: NOW_ISO,
        soc:      num(e.Soc),
        voltage:  num(e.Voltage),
        power:    num(e.Power),
        setpoint: num(e.AcPowerSetPoint),
        acload:   num(e.acload),
        pac:      num(e.pac)
    };
}

return [
    { topic: 'bat_ost',  payload: build('bat_ost')  },
    { topic: 'bat_west', payload: build('bat_west') },
    { topic: 'bat_big',  payload: build('bat_big')  },
    { topic: 'ess',      payload: buildEss()        }
];

// Format InfluxDB raw output into ui_chart reload payload, per bank.
// Three series per bank: min (cell N), max (cell N), SOC (scaled).
// SOC is mapped from 0..100 to the cell voltage range 2.80..3.60
// so it shares the cell Y axis: y = 2.8 + (SOC/100) * 0.8.

const SOC_Y_MIN = 2.8;
const SOC_Y_SPAN = 0.8;   // 3.6 - 2.8

const data = msg.payload;
let series = [];
if (data && data.results && data.results[0] && Array.isArray(data.results[0].series)) {
    series = data.results[0].series;
} else if (Array.isArray(data) && data[0] && data[0].series) {
    series = data[0].series;
}

const STATE = flow.get('bms_state') || {};

function currentIdx(bank, which) {
    const s = STATE[bank];
    if (!s) return null;
    const entry = s['cell_voltages/' + which + '_index'];
    if (!entry) return null;
    const n = parseInt(entry.value, 10);
    return Number.isFinite(n) ? n : null;
}

function currentSoc(bank) {
    const s = STATE[bank];
    if (!s) return null;
    const e = s['soc/soc_percent'];
    if (!e) return null;
    const n = parseFloat(e.value);
    return Number.isFinite(n) ? n : null;
}

const banks = {
    bat_ost:  { min: [], max: [], soc: [] },
    bat_west: { min: [], max: [], soc: [] },
    bat_big:  { min: [], max: [], soc: [] }
};

for (const ser of series) {
    const bank = ser.tags && ser.tags.bank;
    if (!banks[bank]) continue;
    const cols = ser.columns || [];
    const tIdx   = cols.indexOf('time');
    const minIdx = cols.indexOf('cmin');
    const maxIdx = cols.indexOf('cmax');
    const socIdx = cols.indexOf('soc');
    if (tIdx < 0) continue;
    for (const row of ser.values || []) {
        const t = new Date(row[tIdx]).getTime();
        if (!Number.isFinite(t)) continue;
        if (minIdx >= 0) {
            const v = parseFloat(row[minIdx]);
            if (Number.isFinite(v)) banks[bank].min.push({ x: t, y: v });
        }
        if (maxIdx >= 0) {
            const v = parseFloat(row[maxIdx]);
            if (Number.isFinite(v)) banks[bank].max.push({ x: t, y: v });
        }
        if (socIdx >= 0) {
            const s = parseFloat(row[socIdx]);
            if (Number.isFinite(s)) {
                banks[bank].soc.push({ x: t, y: SOC_Y_MIN + (s / 100) * SOC_Y_SPAN });
            }
        }
    }
}

function label(prefix, idx) {
    return idx != null ? `${prefix} (cell ${idx})` : prefix;
}

function socLabel(bank) {
    const cur = currentSoc(bank);
    return cur != null ? `SOC ${cur.toFixed(0)}% (scaled)` : 'SOC (scaled)';
}

function chartMsg(bank) {
    const mi = currentIdx(bank, 'min');
    const xi = currentIdx(bank, 'max');
    return {
        topic: bank,
        payload: [{
            series: [label('min', mi), label('max', xi), socLabel(bank)],
            data:   [banks[bank].min, banks[bank].max, banks[bank].soc],
            labels: ['']
        }]
    };
}

return [chartMsg('bat_ost'), chartMsg('bat_west'), chartMsg('bat_big')];
